package com.smartdoc.ai.provider;
import com.smartdoc.ai.SecretPersistenceException; import java.time.LocalDateTime; import java.util.*; import java.util.concurrent.*;
public class ProviderSecretVault { private final AiProviderMapper mapper; private final Optional<SecretCipher> cipher; private final ConcurrentMap<String,String> volatileKeys=new ConcurrentHashMap<>(); public ProviderSecretVault(AiProviderMapper m,Optional<SecretCipher> c){mapper=m;cipher=c;} private static String slot(long u,long p){return u+":"+p;} public boolean persistenceAvailable(){return cipher.isPresent();} public boolean keyConfigured(long u,long p,AiProviderConfig r){return load(u,p,r).isPresent();}
 public void save(long u,long p,String key,AiProviderConfig row){if(key==null||key.trim().isEmpty())throw new IllegalArgumentException("API key is required");String value=key.trim();if(cipher.isPresent()){if(mapper.updateEncryptedKeyOwned(p,u,cipher.get().encrypt(value,slot(u,p)),LocalDateTime.now())!=1)throw new SecretPersistenceException("AI key storage failed");volatileKeys.remove(slot(u,p));}else{volatileKeys.put(slot(u,p),value);}}
 public Optional<String> load(long u,long p,AiProviderConfig row){if(row==null)return Optional.empty();if(cipher.isPresent()&&row.getEncryptedApiKey()!=null)return Optional.of(cipher.get().decrypt(row.getEncryptedApiKey(),slot(u,p)));return Optional.ofNullable(volatileKeys.get(slot(u,p)));}
 public void clear(long u,long p){volatileKeys.remove(slot(u,p));if(cipher.isPresent()&&mapper.clearEncryptedKeyOwned(p,u,LocalDateTime.now())!=1)throw new SecretPersistenceException("AI key removal failed");}
}
